import React, { useState, useEffect, useRef } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useLanguage } from '../context/LanguageContext';
import '../styles/dialogues.css';

const Dialogues = () => {
  const { theme } = useParams();
  const navigate = useNavigate();
  const { currentLanguage } = useLanguage();
  const [dialogue, setDialogue] = useState([]);
  const [currentPhraseIndex, setCurrentPhraseIndex] = useState(0);
  const [isPlaying, setIsPlaying] = useState(false);
  const [isPaused, setIsPaused] = useState(false);
  const [availableThemes, setAvailableThemes] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [progress, setProgress] = useState(0);
  const [currentTime, setCurrentTime] = useState(0);
  const [totalTime, setTotalTime] = useState(0);
  const [volume, setVolume] = useState(1);
  const [showTranslations, setShowTranslations] = useState(false);
  const [isFullscreen, setIsFullscreen] = useState(false);

  const audioRef = useRef(null);
  const progressIntervalRef = useRef(null);
  const dialogueContainerRef = useRef(null);

  // Carregar temas disponíveis
  const loadAvailableThemes = async () => {
    try {
      const themes = [
        'airport', 'booking_flight', 'commuting', 'morning_routine',
        'ordering_food', 'shopping', 'small_talk', 'weekend_plans'
      ];
      setAvailableThemes(themes);
    } catch (error) {
      console.error('Erro ao carregar temas:', error);
    }
  };

  // Carregar diálogo específico
  const loadDialogue = async (themeName) => {
    try {
      setLoading(true);
      setError(null);

      let response;
      try {
        response = await fetch(`/dialogues/${currentLanguage}/${themeName}.txt`);
        if (!response.ok) throw new Error('Arquivo não encontrado');
      } catch {
        // Fallback para português
        response = await fetch(`/dialogues/pt/${themeName}.txt`);
        if (!response.ok) throw new Error('Arquivo não encontrado em nenhum idioma');
      }

      const text = await response.text();
      const parsedDialogue = parseDialogue(text);
      setDialogue(parsedDialogue);
      setCurrentPhraseIndex(0);
    } catch (error) {
      console.error('Erro ao carregar diálogo:', error);
      setError('Erro ao carregar o diálogo');
    } finally {
      setLoading(false);
    }
  };

  // Processar texto do diálogo
  const parseDialogue = (text) => {
    const lines = text.split('\n').filter(line => line.trim());
    return lines.map((line, index) => ({
      id: index,
      text: line.trim(),
      audioPath: `/audio/${currentLanguage}/${theme}/line_${index}.mp3`
    }));
  };

  // Reproduzir áudio
  const playAudio = (audioPath) => {
    if (audioRef.current) {
      audioRef.current.src = audioPath;
      audioRef.current.play().catch(error => {
        console.error('Erro ao reproduzir áudio:', error);
      });
    }
  };

  // Reproduzir frase atual
  const playCurrentPhrase = () => {
    if (dialogue[currentPhraseIndex]) {
      playAudio(dialogue[currentPhraseIndex].audioPath);
    }
  };

  // Navegar entre frases
  const nextPhrase = () => {
    if (currentPhraseIndex < dialogue.length - 1) {
      setCurrentPhraseIndex(currentPhraseIndex + 1);
    }
  };

  const prevPhrase = () => {
    if (currentPhraseIndex > 0) {
      setCurrentPhraseIndex(currentPhraseIndex - 1);
    }
  };

  // Effects
  useEffect(() => {
    loadAvailableThemes();
  }, []);

  useEffect(() => {
    if (theme) {
      loadDialogue(theme);
    }
  }, [theme, currentLanguage]);

  // Renderização
  if (!theme) {
    return (
      <div className="dialogues-container">
        <h1>Diálogos</h1>
        <div className="themes-grid">
          {availableThemes.map(themeName => (
            <div 
              key={themeName}
              className="theme-card"
              onClick={() => navigate(`/dialogues/${themeName}`)}
            >
              <h3>{themeName.replace('_', ' ').toUpperCase()}</h3>
            </div>
          ))}
        </div>
      </div>
    );
  }

  if (loading) {
    return (
      <div className="dialogues-container">
        <div className="loading">Carregando diálogo...</div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="dialogues-container">
        <div className="error">{error}</div>
        <button onClick={() => navigate('/dialogues')}>Voltar aos Temas</button>
      </div>
    );
  }

  return (
    <div className="dialogues-container">
      <div className="dialogue-header">
        <button onClick={() => navigate('/dialogues')}>← Voltar aos Temas</button>
        <h1>{theme.replace('_', ' ').toUpperCase()}</h1>
      </div>

      <div className="dialogue-content">
        {dialogue.length > 0 && (
          <>
            <div className="phrase-display">
              <div className="phrase-counter">
                {currentPhraseIndex + 1} / {dialogue.length}
              </div>
              <div className="phrase-text">
                {dialogue[currentPhraseIndex]?.text}
              </div>
            </div>

            <div className="controls">
              <button 
                onClick={prevPhrase} 
                disabled={currentPhraseIndex === 0}
              >
                ← Anterior
              </button>

              <button onClick={playCurrentPhrase}>
                🔊 Reproduzir
              </button>

              <button 
                onClick={nextPhrase} 
                disabled={currentPhraseIndex === dialogue.length - 1}
              >
                Próxima →
              </button>
            </div>
          </>
        )}
      </div>

      <audio ref={audioRef} />
    </div>
  );
};

export default Dialogues;
